    READ_IN_MUTABLE_PARAMS;
    [[maybe_unused]] const std::uint64_t aNonceWordA = TwistMix64::DiffuseB(pNonce * 0xEC48109F3247F865ULL + 0x9E2ABCFC6ED9BD3BULL);
