            //
            aOrbiterG = ((aOrbiterG + aOrbiterE) + 0x0425B77236055CDCULL) + aTwistOrbiterUpdateSaltC[(((255U - aIndex) + 100U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterG) ^ 0xB34858F9C5BE2470ULL;
