            aWandererA = aWandererA ^ (((RotL64(aCross, 47U) + RotL64(aOrbiterJ, 47U)) + aOrbiterD) + aTwistWandererUpdateSaltB[((aIndex + 187U)) & S_SALT1]);
            aWandererC = aWandererC + (((RotL64(aScatter, 53U) + aOrbiterI) + RotL64(aOrbiterD, 39U)) + RotL64(aCarry, 35U));
            aWandererB = aWandererB ^ ((RotL64(aPrevious, 27U) + RotL64(aOrbiterB, 27U)) + aOrbiterJ);
