            aScatter = (RotL64(aCarry, 5U) ^ RotL64(aIngress, 39U)) + (RotL64(aPrevious, 20U) + RotL64(aCross, 57U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterD = ((aWandererD + RotL64(aCross, 28U)) + RotL64(aCarry, 11U)) + 0x4106193E294317CEULL;
            aOrbiterE = (aWandererF + RotL64(aScatter, 39U)) + 0x0580BC65B245AE75ULL;
