            aScatter = (RotL64(aCross, 26U) + RotL64(aPrevious, 51U)) ^ (RotL64(aIngress, 13U) + RotL64(aCarry, 39U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterH = ((aWandererA + RotL64(aIngress, 12U)) + RotL64(aCarry, 13U)) + 0x2916CC23860C60EFULL;
            aOrbiterB = (((aWandererJ + RotL64(aPrevious, 23U)) + RotL64(aCarry, 43U)) + 0x39B6E723ED14F59AULL) + aTwistOrbiterAssignSaltB[((aIndex + 74U)) & S_SALT1];
            aOrbiterG = (aWandererC + RotL64(aScatter, 5U)) + 0x6CD9D1A94B7566A7ULL;
