            aOrbiterE = ((aOrbiterE + aOrbiterB) + 0xA4ED828BCD80AFCCULL) + aKeyRotateBOrbiterUpdateSaltA[((aIndex + 184U)) & S_SALT1];
            aOrbiterF = ((aOrbiterF ^ aOrbiterE) ^ 0x918555FCB493B2C9ULL) ^ aKeyRotateBOrbiterUpdateSaltB[(((255U - aIndex) + 85U)) & S_SALT1];
