            aOrbiterB = ((aWandererB + RotL64(aPrevious, 29U)) + RotL64(aCarry, 27U)) + 0x967EDED0BFA567EEULL;
            aOrbiterK = ((aWandererF + RotL64(aScatter, 47U)) + 0x507406C312E33D2CULL) + aKeyRotateBOrbiterAssignSaltE[((aIndex + 103U)) & S_SALT1];
            aOrbiterI = ((aWandererI + RotL64(aIngress, 13U)) + RotL64(aCarry, 11U)) + 0x10AA12EB8B09868EULL;
            aOrbiterJ = (((aWandererE + RotL64(aCross, 51U)) + RotL64(aCarry, 37U)) + 0x0CDD07E9B3025569ULL) + aKeyRotateBOrbiterAssignSaltC[(((255U - aIndex) + 21U)) & S_SALT1];
            aOrbiterD = (aWandererD + RotL64(aScatter, 22U)) + 0xF285CDFA2E1BCB42ULL;
            aOrbiterH = (aWandererG + RotL64(aPrevious, 43U)) + 0x827A8F0A20BBC266ULL;
            aOrbiterG = (aWandererJ + RotL64(aCross, 3U)) + 0x033C17AC5BB4973BULL;
            //
            aOrbiterF = (aOrbiterF + aOrbiterE) + 0xB2829345061DE4D7ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterF) ^ 0x10AB38F0517456C7ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x8CFE3F2F39DF998DULL), 27U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterK) + 0xB952D0BEF98D5A03ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterE) ^ 0xBAF93A81F6320D2EULL;
            aOrbiterI = RotL64((aOrbiterI * 0x049B16F6B4A58D89ULL), 41U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterF) + 0x5EF811EBD7D27A8DULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterK) ^ 0xC4C6E3648833E44DULL;
